effect.shader:
const float TAU = 6.28318530718;

void main() {
    vec4 color = texture(inputImg, acScreenNorm);

    vec2 offset = (acScreenNorm - center) * vec2(acAspect, 1.0);
    // O -90° põe o zero no topo, como num relógio. Sem isso a varredura
    // começaria na direita, que não é onde ninguém espera.
    float angle = atan(offset.y, offset.x) - radians(startAngle) + TAU * 0.25;

    float position = fract(angle / TAU);
    if (direction == 1) {
        position = 1.0 - position;
    } else if (direction == 2) {
        // Abre para os dois lados ao mesmo tempo: a mesma fração de cada lado.
        position = abs(position * 2.0 - 1.0);
    }

    float cut = completion * 0.01;
    float soft = max(feather, 0.0005);
    float mask = smoothstep(cut - soft, cut + soft, position);

    fragColor = vec4(color.rgb, color.a * mask);
}
